<?php use App\Core\Money; ?>
<div class="sales-page"><div class="sales-hero"><h1><?=e($title)?></h1><p>Build a clear commercial document with live totals, tax and customer context.</p></div>
<?php $errors=flash('errors',[]); if($errors):?><div class="alert alert-error"><?php foreach($errors as $x):?><div><?=e($x)?></div><?php endforeach;?></div><?php endif;?>
<form class="sales-card" method="post" action="<?=url($isNew?'/admin/'.$slug:'/admin/'.$slug.'/'.$doc['id'])?>"><?=csrf_field()?><div class="sales-card-head"><h2>Document details</h2><span class="pill">Draft workspace</span></div><div class="sales-card-body"><div class="sales-form-grid"><div class="sales-field"><label>Customer</label><select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=($doc['customer_id']??0)==$c['id']?'selected':''?>><?=e($c['code'].' · '.$c['company_name'])?></option><?php endforeach;?></select></div><div class="sales-field"><label>Currency</label><select name="currency"><?php foreach(Money::CURRENCIES as $c=>$v):?><option value="<?=$c?>" <?=($doc['currency']??'AED')===$c?'selected':''?>><?=e($c.' · '.$v['label'])?></option><?php endforeach;?></select></div><div class="sales-field"><label>Issue date</label><input type="date" name="issue_date" value="<?=e($doc['issue_date']??date('Y-m-d'))?>"></div><div class="sales-field"><label><?= $type==='quotation'?'Valid until':'Due date' ?></label><input type="date" name="<?= $type==='quotation'?'valid_until':'due_date' ?>" value="<?=e($doc['valid_until']??$doc['due_date']??'')?>"></div><div class="sales-field"><label>Discount</label><input id="discount" name="discount" inputmode="decimal" value="<?=e($doc['discount']??'0.00')?>"></div><div class="sales-field"><label>Tax %</label><input id="tax_rate" name="tax_rate" inputmode="decimal" value="<?=e($doc['tax_rate']??'0.00')?>"></div></div></div><div class="sales-card-head"><h2>Line items</h2><button type="button" class="btn btn-ghost" id="add-line">+ Add line</button></div><div class="sales-card-body"><div class="sales-line-head"><span>SKU</span><span>Description</span><span>Qty</span><span>Unit price</span><span>Line total</span><span></span></div><div id="lines"><?php foreach($lines as $l):?><div class="sales-line"><input name="line_sku[]" placeholder="SKU" value="<?=e($l['sku']??'')?>"><input name="line_description[]" placeholder="Service or product description" required value="<?=e($l['description']??'')?>"><input class="qty" name="line_qty[]" placeholder="1" value="<?=e($l['qty']??'1')?>"><input class="price" name="line_unit_price[]" placeholder="0.00" value="<?=e($l['unit_price']??'0')?>"><output class="line-total">0.00</output><button type="button" class="btn btn-ghost remove-line" aria-label="Remove line">×</button></div><?php endforeach;?></div><div class="sales-total"><span>Estimated total</span><strong id="grand-total">0.00</strong></div></div><div class="sales-card-body"><div class="sales-field wide"><label>Notes</label><textarea name="notes" rows="3" placeholder="Payment terms, delivery notes or internal context"><?=e($doc['notes']??'')?></textarea></div><div class="sales-actions"><a class="btn btn-ghost" href="<?=url('/admin/'.$slug)?>">Cancel</a><button class="btn btn-primary">Save <?=e(ucwords(str_replace('_',' ',$type)))?></button></div></div></form></div>
<script>(()=>{const wrap=document.querySelector('#lines'),total=document.querySelector('#grand-total');const calc=()=>{let s=0;wrap.querySelectorAll('.sales-line').forEach(r=>{const q=parseFloat(r.querySelector('.qty')?.value||0),p=parseFloat(r.querySelector('.price')?.value||0),v=q*p;r.querySelector('.line-total').textContent=v.toFixed(2);s+=v});const d=parseFloat(document.querySelector('#discount')?.value||0),t=parseFloat(document.querySelector('#tax_rate')?.value||0);total.textContent=Math.max(0,(s-d)*(1+t/100)).toFixed(2)};const bind=r=>{r.querySelectorAll('input').forEach(x=>x.addEventListener('input',calc));r.querySelector('.remove-line').onclick=()=>{if(wrap.children.length>1)r.remove();calc()}};wrap.querySelectorAll('.sales-line').forEach(bind);document.querySelector('#add-line').onclick=()=>{const r=wrap.firstElementChild.cloneNode(true);r.querySelectorAll('input').forEach(x=>x.value='');r.querySelector('.qty').value='1';wrap.append(r);bind(r);calc()};document.querySelectorAll('#discount,#tax_rate').forEach(x=>x.addEventListener('input',calc));calc()})();</script>
